async function loadProfile(){if(!token)return;try{const p=await api('staff?select=id,restaurant_id,display_name,role,active&auth_user_id=eq.'+session.user.id,{token});if(!p?.[0]?.active)throw Error('Your account is not assigned to an active TAP3 restaurant staff profile. Contact the owner.');setStaff(p[0]);setError('')}catch(e){setError(e.message);setStaff(null)}}
