useEffect(()=>{const timer=setInterval(()=>setClock(Date.now()),1000);return()=>clearInterval(timer)},[]);const [soundEnabled,setSoundEnabled]=useState(false);const audioRef=useRef(null),seenRef=useRef(null),redRef=useRef(new Set());const token=session?.access_token;const chooseDeviceMode=m=>{setDeviceMode(m);localStorage.setItem('tap3_device_mode',m)};
