async function login(e){e.preventDefault();setBusy(true);setError('');try{const s=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email,password}});sessionStorage.setItem(STORE,JSON.stringify(s));setSession(s);setPassword('')}catch(e){setError(e.message)}finally{setBusy(false)}}
