async function sync(){if(!staff||!token)return;try{const id=encodeURIComponent(staff.restaurant_id);const [t,m,o,r]=await Promise.all([api('dining_tables?select=id,label&restaurant_id=eq.'+id+'&order=label',{token}),api('menu_items?select=id,name,category,price_cents,image_url,tile_color,active&restaurant_id=eq.'+id+'&order=name',{token}),api('tickets?select=id,table_id,created_by,status,created_at,kitchen_ready_at,kitchen_ready_by,order_source,packaging_instructions,customer_name,ticket_items(id,item_name,quantity,unit_price_cents,station,seat_number,notes)&restaurant_id=eq.'+id+'&order=created_at.desc&limit=500',{token}),api('restaurants?select=kds_yellow_minutes,kds_red_minutes&id=eq.'+id,{token})]);if(r?.[0]){setKdsSettings({yellow:r[0].kds_yellow_minutes,red:r[0].kds_red_minutes});}setTables(t);setMenu(m);setTickets(o);setTable(v=>v||t[0]?.id||'');setLastSync(new Date());setError('')}catch(e){setError('Sync failed: '+e.message)}}
