const categoryColor=c=>({'Bar':'#8B5CF6','Wings':'#F97316','Burgers':'#F43F5E','Appetizers':'#0EA5E9','Entrees':'#14B8A6','Sides':'#EAB308'}[c]||'#2563EB');
const canOrder=['owner','manager','server','bartender'].includes(staff?.role);const add=m=>setCart(c=>{const existing=c.find(x=>x.id===m.id&&x.seat_number===seat&&x.notes===itemNote);return existing?c.map(x=>x===existing?{...x,quantity:x.quantity+1}:x):[...c,{...m,quantity:1,seat_number:seat,notes:itemNote}]});
