async function status(o,value){let reason='';if(value==='void'){if(!['owner','manager'].includes(staff?.role))return;const input=window.prompt('Reason for voiding this ticket (required):');if(input===null)return;reason=input.trim();if(!reason){setError('A reason is required to void a ticket.');return}if(reason.length>500){setError('Void reason must be 500 characters or fewer.');return}if(!window.confirm('Void this ticket? This action is recorded in the audit log.'))return}setBusy(true);setError('');try{await api('tickets?id=eq.'+o.id,{method:'PATCH',token,headers:reason?{'x-tap3-void-reason':reason}:{},body:{status:value,updated_at:new Date().toISOString()}});await sync()}catch(e){setError(e.message)}finally{setBusy(false)}}
